const crypto = require('crypto');
const secret = $env.COPILOT_INGEST_HMAC_SECRET;
if (!secret) throw new Error('COPILOT_INGEST_HMAC_SECRET is required');
const integrationId = 'n8n-calendar-v1';
const endpointPath = '/api/v1/integrations/work-events:ingest';
const sourceAccountRef = $env.GOOGLE_SOURCE_ACCOUNT_REF;
const calendarRef = $env.GOOGLE_CALENDAR_REF;
if (!sourceAccountRef || !calendarRef) throw new Error('Google source references are required');
return items.filter(({json:e}) => e.extendedProperties?.private?.acme_work_event === 'v1').map(({json:e}) => {
  const p = e.extendedProperties.private;
  const start = new Date(e.start?.dateTime || '');
  const end = new Date(e.end?.dateTime || '');
  const duration = Math.round((end - start) / 60000);
  const event = {schema_version:'1.0',source:'google_calendar',source_account_ref:sourceAccountRef,calendar_id:calendarRef,event_id:String(e.id || ''),event_updated_at:String(e.updated || ''),person_ref:String(p.person_ref || ''),project_code:String(p.project_code || ''),work_date:start.toISOString().slice(0,10),duration_minutes:duration,description:String(p.work_description || '')};
  if (!/^[a-z0-9-]{3,64}$/.test(event.person_ref) || !/^[A-Z0-9_-]{2,32}$/.test(event.project_code) || !event.event_id || !/^\d{4}-\d{2}-\d{2}T/.test(event.event_updated_at) || duration < 15 || duration > 1440 || duration % 15 || !event.description || event.description.length > 200) throw new Error('Calendar event failed bounded WorkEvent validation');
  const body = JSON.stringify(event);
  const timestamp = Math.floor(Date.now()/1000).toString();
  const nonce = crypto.randomUUID();
  const bodyHash = crypto.createHash('sha256').update(body).digest('hex');
  const base = ['v1',timestamp,nonce,'POST',endpointPath,bodyHash].join('\n');
  const signature = 'v1=' + crypto.createHmac('sha256',secret).update(base).digest('hex');
  const revision = crypto.createHash('sha256').update(['gcal:v1',event.calendar_id,event.event_id,event.event_updated_at].join('\0')).digest('hex');
  return {json:{body,headers:{'Content-Type':'application/json','X-Acme-Integration-Id':integrationId,'X-Acme-Timestamp':timestamp,'X-Acme-Nonce':nonce,'X-Acme-Idempotency-Key':'sha256:'+revision,'X-Acme-Signature':signature}}};
});
